let productFaqs={};
fetch('product-faqs.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{productFaqs=data;if(document.querySelector('#serviceDialog').open)renderProductFaqs(document.querySelector('#serviceContact').dataset.service)}).catch(()=>{document.querySelector('#serviceFaqs').textContent='Contact Blu for product-specific questions.'});
function renderProductFaqs(key){const host=document.querySelector('#serviceFaqs');host.replaceChildren();for(const [q,a] of productFaqs[key]||[]){const details=document.createElement('details'),summary=document.createElement('summary'),p=document.createElement('p');summary.textContent=q;p.textContent=a;details.append(summary,p);host.append(details);}document.querySelector('#rateProduct').value=key;}
document.querySelectorAll('[data-local-product]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showService(a.dataset.localProduct)}));
for(const [id,target] of [['rateFromProduct','rate-inquiry'],['applyFromProduct','application']])document.getElementById(id).addEventListener('click',()=>{document.querySelector('#serviceDialog').close();document.getElementById(target).scrollIntoView({behavior:'smooth'})});
let rateText='';const rateForm=document.querySelector('#rateForm');rateForm.addEventListener('submit',e=>{e.preventDefault();if(!rateForm.reportValidity())return;const d=new FormData(rateForm),product=document.querySelector('#rateProduct').selectedOptions[0].text;rateText=`Hello Blu Capital,\n\nI would like a personalized financing rate.\n\nCompany: ${d.get('company').trim()}\nName: ${d.get('name').trim()}\nEmail: ${d.get('email').trim()}\nPhone: ${d.get('phone').trim()}\nProduct: ${product}\nAmount needed: ${d.get('amount')}\n\nPlease contact me about available options and the application requirements.\n\nThank you.`;document.querySelector('#ratePreview').textContent=rateText;document.querySelector('#rateSend').href='mailto:sales@blucapital.us?subject='+encodeURIComponent('Financing rate inquiry: '+d.get('company').trim())+'&body='+encodeURIComponent(rateText);document.querySelector('#rateResult').hidden=false;});rateForm.addEventListener('input',()=>{document.querySelector('#rateResult').hidden=true;document.querySelector('#rateStatus').textContent=''});document.querySelector('#rateCopy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(rateText);document.querySelector('#rateStatus').textContent='Request copied.'}catch{document.querySelector('#rateStatus').textContent='Select and copy your request above.'}});
// Load third-party application/booking services only when their sections approach the viewport.
const frames=document.querySelectorAll('iframe[data-src]');if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.src=entry.target.dataset.src;observer.unobserve(entry.target)}},{rootMargin:'400px'});frames.forEach(f=>observer.observe(f))}else frames.forEach(f=>f.src=f.dataset.src);
let callbackText='';const callbackForm=document.querySelector('#callbackForm'),callbackDate=document.querySelector('#callbackDate');const now=new Date();callbackDate.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
callbackForm.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(callbackForm);const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:d.get('timezone'),year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const zonedNow=`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;callbackDate.setCustomValidity(`${d.get('date')}T${d.get('time')}`<=zonedNow?'Please select a future date and time.':'');if(!callbackForm.reportValidity())return;callbackText=`Hello Blu Capital,\n\nPlease contact me to arrange a conversation.\n\nName: ${d.get('name').trim()}\nEmail: ${d.get('email').trim()}\nPhone: ${d.get('phone').trim()}\nPreferred date: ${d.get('date')}\nPreferred time: ${d.get('time')}\nTimezone: ${d.get('timezone')}\n\n${d.get('topic').trim()}\n\nPlease confirm availability. I understand this is a request, not a confirmed booking.`;document.querySelector('#callbackPreview').textContent=callbackText;document.querySelector('#callbackSend').href='mailto:sales@blucapital.us?subject='+encodeURIComponent('Callback request')+'&body='+encodeURIComponent(callbackText);document.querySelector('#callbackResult').hidden=false;});
callbackForm.addEventListener('input',()=>{callbackDate.setCustomValidity('');document.querySelector('#callbackResult').hidden=true;document.querySelector('#callbackStatus').textContent=''});document.querySelector('#callbackCopy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(callbackText);document.querySelector('#callbackStatus').textContent='Request copied.'}catch{document.querySelector('#callbackStatus').textContent='Select and copy your request above.'}});
